using System;
using System.Linq;
using FrameTools;

internal static class ProtocolTests
{
    // Hand-calculated wire vectors: they are not generated by the codec under test.
    private const string Read645 = "68 01 00 00 00 00 00 68 11 04 33 33 34 33 B3 16";
    private const string Energy645 = "68 01 00 00 00 00 00 68 91 08 33 33 34 33 AB 89 67 45 17 16";
    private const string Local = "68 0C 00 40 03 01 01 03 00 E8 30 16";
    private const string Uplink = "68 10 00 10 00 68 4B 06 01 44 01 00 00 01 0C 60 01 01 00 00 01 00 07 16";
    private static int passed;
    private static int failed;

    private static void Check(bool condition, string message)
    {
        if (!condition)
        {
            throw new Exception(message);
        }
    }

    private static void Run(string name, Action test)
    {
        try
        {
            test();
            passed++;
            Console.WriteLine("PASS " + name);
        }
        catch (Exception e)
        {
            failed++;
            Console.WriteLine("FAIL " + name + ": " + e.Message);
        }
    }

    private static void Reject(Action action)
    {
        bool rejected = false;
        try
        {
            action();
        }
        catch (FormatException)
        {
            rejected = true;
        }
        Check(rejected, "Expected FormatException");
    }

    private static FrameResult Parse(ProtocolKind protocol, string text)
    {
        return FrameCodec.Parse(protocol, text);
    }

    private static FrameField Field(FrameResult result, string name)
    {
        return result.Fields.Single(f => f.Name == name);
    }

    private static string Mutate(string text, int index, byte value)
    {
        byte[] bytes = Hex.Parse(text);
        bytes[index] = value;
        return Hex.Format(bytes);
    }

    [STAThread]
    private static int Main()
    {
        Console.OutputEncoding = System.Text.Encoding.UTF8;
        Run("HEX separators and prefixes", delegate
        {
            Check(Hex.Format(Hex.Parse("0x68,0x01:02-03\r\n04")) == "68 01 02 03 04", "Hex input mismatch");
        });
        Run("HEX odd nibble rejected", delegate { Reject(delegate { Hex.Parse("681"); }); });
        Run("HEX invalid character rejected", delegate { Reject(delegate { Hex.Parse("68 ZZ"); }); });
        Run("645 fixed request vector", delegate
        {
            FrameResult r = Parse(ProtocolKind.Dlt645, Read645);
            Check(r.IsFrameValid, string.Join(";", r.Errors));
            Check(Field(r, "通信地址 A").Meaning.StartsWith("000000000001"), "Address order");
            Check(Field(r, "数据标识 DI").Meaning.StartsWith("00010000"), "DI order or -33H");
            Check(!r.Fields.Any(f => f.Name == "当前正向有功总电能"), "Request decoded as response");
        });
        Run("645 builder matches independent vector", delegate
        {
            Check(Hex.Format(FrameCodec.Build645("000000000001", 0x11, Hex.Parse("00 00 01 00"), 0)) == Read645, "Wire bytes differ");
        });
        Run("645 four FE excluded from CS and length", delegate
        {
            byte[] frame = FrameCodec.Build645("000000000001", 0x11, Hex.Parse("00 00 01 00"), 4);
            Check(Hex.Format(frame) == "FE FE FE FE " + Read645, "Preamble bytes");
            FrameResult r = Parse(ProtocolKind.Dlt645, Hex.Format(frame));
            Check(r.IsFrameValid && Field(r, "数据标识 DI").Offset == 14, "Preamble offset or CS");
        });
        Run("645 BCD energy has exact scale", delegate
        {
            FrameResult r = Parse(ProtocolKind.Dlt645, Energy645);
            Check(r.IsFrameValid, string.Join(";", r.Errors));
            Check(Field(r, "当前正向有功总电能").Meaning == "123456.78 kWh", "BCD or decimal scale");
        });
        Run("645 invalid BCD retained as raw data", delegate
        {
            byte[] bytes = FrameCodec.Build645("000000000001", 0x91, Hex.Parse("00 00 01 00 FF FF FF FF"), 0);
            FrameResult r = Parse(ProtocolKind.Dlt645, Hex.Format(bytes));
            Check(r.IsFrameValid && r.Notes.Any(n => n.Contains("无效 BCD")), "Missing invalid BCD note");
            Check(!r.Fields.Any(f => f.Name == "当前正向有功总电能"), "Invalid data converted to number");
        });
        Run("645 voltage has exact scale", delegate
        {
            byte[] bytes = FrameCodec.Build645("000000000001", 0x91, Hex.Parse("00 01 01 02 01 22"), 0);
            FrameResult r = Parse(ProtocolKind.Dlt645, Hex.Format(bytes));
            Check(r.IsFrameValid && Field(r, "相电压").Meaning == "220.1 V", "Voltage scale");
        });
        Run("645 +33H wraps modulo 256", delegate
        {
            byte[] bytes = FrameCodec.Build645("000000000001", 0x16, Hex.Parse("FF CD 00"), 0);
            Check(Hex.Format(bytes.Skip(10).Take(3).ToArray()) == "32 00 33", "Modulo addition");
            Check(Field(Parse(ProtocolKind.Dlt645, Hex.Format(bytes)), "数据域 DATA").Meaning.EndsWith("FF CD 00"), "Modulo subtraction");
        });
        Run("645 address request carries no DI", delegate
        {
            FrameResult r = Parse(ProtocolKind.Dlt645, Hex.Format(FrameCodec.Build645("AAAAAAAAAAAA", 0x13, new byte[0], 0)));
            Check(r.IsFrameValid && !r.Fields.Any(f => f.Name == "数据标识 DI"), "Address request misread");
        });
        Run("645 abnormal response carries ERR", delegate
        {
            FrameResult r = Parse(ProtocolKind.Dlt645, Hex.Format(FrameCodec.Build645("000000000001", 0xD1, new byte[] { 4 }, 0)));
            Check(r.IsFrameValid && Field(r, "异常信息 ERR").Meaning.Contains("04"), "ERR decoding");
            Check(!r.Fields.Any(f => f.Name == "数据标识 DI"), "ERR misread as DI");
        });
        Run("645 second marker rejected", delegate { Check(!Parse(ProtocolKind.Dlt645, Mutate(Read645, 7, 0x69)).IsFrameValid, "Marker accepted"); });
        Run("645 wrong length diagnosed", delegate { Check(Parse(ProtocolKind.Dlt645, Mutate(Read645, 9, 5)).Errors.Any(e => e.Contains("长度不符")), "Length accepted"); });
        Run("645 wrong CS diagnosed", delegate { Check(Parse(ProtocolKind.Dlt645, Mutate(Read645, 14, 0)).Errors.Any(e => e.Contains("校验和错误")), "CS accepted"); });
        Run("645 wrong end diagnosed", delegate { Check(!Parse(ProtocolKind.Dlt645, Mutate(Read645, 15, 0)).IsFrameValid, "End accepted"); });
        Run("645 non-BCD address rejected", delegate { Reject(delegate { FrameCodec.Build645("123456789ABC", 0x11, new byte[0], 0); }); });
        Run("645 read length limit", delegate { Reject(delegate { FrameCodec.Build645("000000000001", 0x11, new byte[201], 0); }); });
        Run("645 write length limit", delegate { Reject(delegate { FrameCodec.Build645("000000000001", 0x14, new byte[51], 0); }); });
        Run("local fixed request vector", delegate
        {
            FrameResult r = Parse(ProtocolKind.CsgLocal, Local);
            Check(r.IsFrameValid, string.Join(";", r.Errors));
            Check(Field(r, "数据标识 DI").Meaning.StartsWith("E8000301"), "Local DI order");
        });
        Run("local builder matches independent vector", delegate
        {
            Check(Hex.Format(FrameCodec.BuildLocal(0x40, "", "", 3, 1, Hex.Identifier("E8000301"), new byte[0])) == Local, "Local wire bytes differ");
        });
        Run("local ADD inserts 12 bytes and preserves 8-bit SEQ", delegate
        {
            byte[] bytes = FrameCodec.BuildLocal(0x60, "440106000001", "123456789012", 3, 0xFF, Hex.Identifier("E8030304"), Hex.Parse("AB"));
            FrameResult r = Parse(ProtocolKind.CsgLocal, Hex.Format(bytes));
            Check(bytes.Length == 25 && bytes[1] == 25 && r.IsFrameValid, "Addressed length or CS");
            Check(Field(r, "源地址 ASRC").Raw == "01 00 00 06 01 44", "Source byte order");
            Check(Field(r, "目的地址 ADST").Meaning.StartsWith("123456789012"), "Destination byte order");
            Check(Field(r, "帧序列 SEQ").Raw == "FF", "SEQ truncated to four bits");
        });
        Run("local missing ADD addresses diagnosed", delegate
        {
            Check(Parse(ProtocolKind.CsgLocal, Mutate(Local, 3, 0x60)).Errors.Any(e => e.Contains("ADD=1")), "Missing address accepted");
        });
        Run("local missing builder address rejected", delegate { Reject(delegate { FrameCodec.BuildLocal(0x60, "", "", 3, 1, Hex.Identifier("E8000301"), new byte[0]); }); });
        Run("local wrong total length diagnosed", delegate { Check(!Parse(ProtocolKind.CsgLocal, Mutate(Local, 1, 13)).IsFrameValid, "Local length accepted"); });
        Run("local CS excludes header and length", delegate
        {
            FrameResult r = Parse(ProtocolKind.CsgLocal, Local);
            Check(Field(r, "校验和 CS").Meaning.Contains("30"), "CS includes local header");
        });
        Run("uplink fixed vector and 7-byte address", delegate
        {
            FrameResult r = Parse(ProtocolKind.CsgUplink, Uplink);
            Check(r.IsFrameValid, string.Join(";", r.Errors));
            Check(Field(r, "省地市区县码 A1").Meaning.StartsWith("440106"), "A1 byte order");
            Check(Field(r, "终端地址 A2").Meaning.StartsWith("000001"), "A2 byte order");
            Check(Field(r, "首个信息点 DA").Meaning == "p1", "DA bit mapping");
            Check(Field(r, "首个数据标识 DI").Meaning.StartsWith("00010000"), "DI byte order");
        });
        Run("uplink builder uses direct BIN length", delegate
        {
            byte[] bytes = FrameCodec.BuildUplink(0x4B, Hex.Parse("06 01 44 01 00 00 01"), 0x0C, 0x60, Hex.Parse("01 01 00 00 01 00"));
            Check(Hex.Format(bytes) == Uplink, "Uplink wire bytes differ; expected direct L=16");
        });
        Run("uplink repeated length must agree", delegate { Check(Parse(ProtocolKind.CsgUplink, Mutate(Uplink, 3, 17)).Errors.Any(e => e.Contains("不一致")), "Repeated length accepted"); });
        Run("uplink rejects national-grid shifted length", delegate
        {
            string value = Mutate(Mutate(Uplink, 1, 0x42), 3, 0x42);
            Check(Parse(ProtocolKind.CsgUplink, value).Errors.Any(e => e.Contains("长度不符")), "Shifted length accepted");
        });
        Run("uplink rejects second start marker", delegate { Check(!Parse(ProtocolKind.CsgUplink, Mutate(Uplink, 5, 0)).IsFrameValid, "Second start accepted"); });
        Run("uplink rejects five-byte address", delegate { Reject(delegate { FrameCodec.BuildUplink(0x4B, new byte[5], 0x0C, 0x60, new byte[0]); }); });
        Run("uplink time tag is split only when TpV is set", delegate
        {
            byte[] bytes = FrameCodec.BuildUplink(0x4B, Hex.Parse("06 01 44 01 00 00 01"), 0x0C, 0xE1, Hex.Parse("01 01 00 00 01 00 01 02 03 04 05"));
            FrameResult r = Parse(ProtocolKind.CsgUplink, Hex.Format(bytes));
            Check(r.IsFrameValid && Field(r, "时间标签 Tp").Raw == "01 02 03 04 05", "Tp boundary");
            Check(Field(r, "应用业务区").Length == 6, "Tp remains in business data");
        });
        Run("uplink missing time tag rejected", delegate { Reject(delegate { FrameCodec.BuildUplink(0x4B, new byte[7], 0x0C, 0xE0, new byte[4]); }); });
        Run("uplink encrypted payload is not interpreted as DA/DI", delegate
        {
            byte[] bytes = FrameCodec.BuildUplink(0x4A, new byte[7], 4, 0x60, Hex.Parse("DE AD BE EF 01 02 03 04"));
            FrameResult r = Parse(ProtocolKind.CsgUplink, Hex.Format(bytes));
            Check(r.IsFrameValid && !r.Fields.Any(f => f.Name == "首个数据标识 DI"), "Encrypted bytes interpreted as DI");
            Check(Field(r, "应用业务区").Raw == "DE AD BE EF 01 02 03 04", "Encrypted data altered");
        });
        Run("uplink FE excluded from CS and length", delegate { Check(Parse(ProtocolKind.CsgUplink, "FE FE " + Uplink).IsFrameValid, "Infrared preamble"); });
        Run("DA multi-point and special mappings", delegate
        {
            Check(FrameCodec.DescribeDa(3, 1) == "p1, p2", "DA multiple bits");
            Check(FrameCodec.DescribeDa(128, 254) == "p2032", "DA upper bound");
            Check(FrameCodec.DescribeDa(0, 0).StartsWith("p0"), "DA terminal");
            Check(FrameCodec.DescribeDa(255, 255).Contains("全部"), "DA all points");
        });
        Run("all partial prefixes report errors without crashing", delegate
        {
            string[] vectors = { Read645, Local, Uplink };
            for (int p = 0; p < vectors.Length; p++)
            {
                byte[] bytes = Hex.Parse(vectors[p]);
                for (int length = 0; length < bytes.Length; length++)
                {
                    FrameResult r = Parse((ProtocolKind)p, Hex.Format(bytes.Take(length).ToArray()));
                    Check(!r.IsFrameValid, "Partial frame accepted at protocol " + p + ", length " + length);
                    Check(r.Fields.All(f => f.Offset >= 0 && f.Offset + f.Length <= length), "Field points beyond input");
                }
            }
        });
        Run("concatenated frames rejected as one input", delegate
        {
            Check(!Parse(ProtocolKind.Dlt645, Read645 + " " + Read645).IsFrameValid, "Multiple frames accepted");
        });
        Run("WinForms constructor loads initial parsed example", delegate
        {
            System.Windows.Forms.Application.EnableVisualStyles();
            using (MainForm form = new MainForm())
            {
                Check(form.Text.StartsWith("FrameTools 0.1.0"), "Window title");
                Check(form.Controls.Count > 0, "Window contains no layout");
            }
        });
        Console.WriteLine("RESULT: " + passed + " passed, " + failed + " failed");
        return failed == 0 ? 0 : 1;
    }
}
